using Crown.Core;
using System.Text.Json.Nodes;

internal static class StageTwentyEightSpecs
{
    private static void Assert(bool value,string text){if(!value)throw new Exception(text);}
    internal static GameState Fixture()
    {
        var s=StageTwentySevenSpecs.Fixture(4);s.Factions[1].Technologies.UnionWith(EpochCatalog.All.Take(5).SelectMany(e=>e.Technologies));
        for(int i=0;i<=4;i++)s.Factions[1].EpochChoices[i]=0;s.Relation(0,1).Trust=80;s.Relation(0,1).Trade=true;return s;
    }
    private static void Step(GameState s)
    {
        if(s.PendingEvent!=null){var e=ProvincialEvents.Current(s);int choice=Enumerable.Range(0,e.Choices.Length).First(i=>s.Player.Gold+e.Choices[i].Gold>=0);Assert(Narrative.Resolve(s,choice).Success,"Could not resolve council");}
        s.Ending=null;Assert(Engine.EndTurn(s).Success,"Could not advance turn");
    }
    private static void Valid(GameState s)=>SaveGame.Deserialize(SaveGame.Serialize(s));
    private static BilateralTreaty Ready(GameState s,TreatyKind kind=TreatyKind.Research,int duration=12)
    {
        Assert(Treaties.Propose(s,1,kind,duration).Success,"Offer failed");var t=s.Treaties.Last();Step(s);Step(s);Assert(t.Status==TreatyStatus.AwaitingPlayer,"Reply missing");return t;
    }
    private static BilateralTreaty Active(GameState s,TreatyKind kind=TreatyKind.Research,int duration=12)
    {var t=Ready(s,kind,duration);Assert(Treaties.Ratify(s,t.Id).Success,"Ratification failed");return t;}
    public static void Run(Action<string,Action> test)
    {
        test("Treaty previews and registry remain read-only including RNG",()=>{var s=Fixture();string json=SaveGame.Serialize(s);Treaties.OfferError(s,0,1,TreatyKind.Research,12);Treaties.AcceptanceScore(s,1,TreatyKind.PeaceGuarantee,24);Treaties.BreachWarning(s,0);Assert(SaveGame.Serialize(s)==json,"Preview mutated state");});
        test("A proposal charges only its sender's embassy fee",()=>{var s=Fixture();double a=s.Player.Gold,b=s.Factions[1].Gold;Assert(Treaties.Propose(s,1,TreatyKind.Research,12).Success&&s.Player.Gold==a-10&&s.Factions[1].Gold==b&&s.Treaties.Single().EscrowFrom==0,"Proposal spent or fabricated a bond");Valid(s);});
        test("A treaty reply actually travels for two turns and awaits explicit player signature",()=>{var s=Fixture();Treaties.Propose(s,1,TreatyKind.Research,12);var t=s.Treaties.Single();Step(s);Assert(t.Status==TreatyStatus.Travelling,"Instant reply");Step(s);Assert(t.Status==TreatyStatus.AwaitingPlayer&&t.SignedTurn==null&&t.EscrowFrom==0,"Automatic ratification");Valid(s);});
        test("A deteriorating diplomatic situation can reject a previously promising offer",()=>{var s=Fixture();Treaties.Propose(s,1,TreatyKind.Research,12);s.Relation(0,1).Trust=-80;Step(s);Step(s);Assert(s.Treaties.Single().Status==TreatyStatus.Rejected&&s.Treaties.Single().EscrowFrom==0,"Acceptance frozen at dispatch");Valid(s);});
        test("Unaffordable malformed legacy and duplicate proposals are atomic",()=>{var s=Fixture();s.Player.Gold=9;string json=SaveGame.Serialize(s);Assert(!Treaties.Propose(s,1,TreatyKind.Research,12).Success&&!Treaties.Propose(s,8,TreatyKind.Research,12).Success&&!Treaties.Propose(s,1,(TreatyKind)9,12).Success&&!Treaties.Propose(s,1,TreatyKind.Research,13).Success&&SaveGame.Serialize(s)==json,"Invalid proposal mutated state");s.Player.Gold=1000;s.EpochCampaign=false;json=SaveGame.Serialize(s);Assert(!Treaties.Propose(s,1,TreatyKind.Research,12).Success&&SaveGame.Serialize(s)==json,"Legacy proposal allowed");});
        test("Research diplomacy requires writing and respects existing wars and embargoes",()=>{var s=Fixture();s.Factions[1].Technologies.Remove("writing");Assert(Treaties.OfferError(s,0,1,TreatyKind.Research,12)!=null,"Skipped writing");s.Factions[1].Technologies.Add("writing");s.Relation(0,1).War=true;Assert(Treaties.OfferError(s,0,1,TreatyKind.Research,12)!=null,"War offer allowed");s.Relation(0,1).War=false;s.Factions[1].TradePolicy=TradePolicy.Embargo;Assert(Treaties.OfferError(s,0,1,TreatyKind.Research,12)!=null&&Treaties.OfferError(s,0,1,TreatyKind.PeaceGuarantee,12)==null,"Embargo policy incorrect");});
        test("Both deposits are actually locked together without instant science",()=>{var s=Fixture();var t=Ready(s);double a=s.Player.Gold,b=s.Factions[1].Gold,science=s.Player.Science;Assert(Treaties.Ratify(s,t.Id).Success&&s.Player.Gold==a-50&&s.Factions[1].Gold==b-50&&t.EscrowFrom+t.EscrowTo==100&&s.Player.Science==science&&t.ExpiresTurn==s.Turn+12,"Ratification created or skipped funds");Valid(s);});
        test("Failed ratification never partially charges the solvent party",()=>{var s=Fixture();var t=Ready(s);s.Factions[1].Gold=49;string json=SaveGame.Serialize(s);Assert(!Treaties.Ratify(s,t.Id).Success&&SaveGame.Serialize(s)==json,"Partial signature charge");});
        test("Rechecking trust at signature prevents stale consent",()=>{var s=Fixture();var t=Ready(s);s.Relation(0,1).Trust=-70;string json=SaveGame.Serialize(s);Assert(!Treaties.Ratify(s,t.Id).Success&&SaveGame.Serialize(s)==json,"Stale partner consent used");});
        test("Declining or timing out never confiscates unsigned deposits",()=>{foreach(bool reject in new[]{true,false}){var s=Fixture();var t=Ready(s);double a=s.Player.Gold,b=s.Factions[1].Gold;if(reject)Assert(Treaties.Reject(s,t.Id).Success,"Decline failed");else{while(s.Turn<t.DeadlineTurn)Step(s);}Assert(t.Status==(reject?TreatyStatus.Rejected:TreatyStatus.Expired)&&t.SignedTurn==null&&t.PayoutFrom+t.PayoutTo==0&&s.Player.Gold>=0&&s.Factions[1].Gold>=0,"Unsigned payout fabricated");Valid(s);}});
        test("A funded research phase derives science from actual income rather than banked science",()=>{var s=Fixture();var t=Active(s);s.Player.Science=1000000;double own=Math.Max(0,Engine.Income(s,0).Science),other=Math.Max(0,Engine.Income(s,1).Science);var control=SaveGame.Deserialize(SaveGame.Serialize(s));control.Treaties=[];control.NextTreatyId=1;Step(s);Step(control);double bonus=Math.Min(5+Math.Min(s.Player.Era,s.Factions[1].Era),Math.Min(own,other)*.15);Assert(t.LastFee==2&&Math.Abs(t.LastScience-bonus)<.00001&&Math.Abs(s.Player.Gold-control.Player.Gold+2)<.00001&&Math.Abs(s.Factions[1].Gold-control.Factions[1].Gold+2)<.00001&&Math.Abs(s.Player.Science-control.Player.Science-bonus)<.00001&&t.FundedPhases==1,"Research phase duplicated income or fees");Valid(s);});
        test("Researchers cannot magnify the same phase by repeated forecasting",()=>{var s=Fixture();var t=Active(s);Step(s);string json=SaveGame.Serialize(s);Treaties.PlannedFees(s,0);Treaties.AcceptanceScore(s,1,t.Kind,t.Duration);Treaties.RatifyError(s,t);Assert(SaveGame.Serialize(s)==json&&!Treaties.Ratify(s,t.Id).Success,"Repeated work or signature");});
        test("Three unilateral unfunded phases compensate the solvent partner without debt",()=>{var s=Fixture();var t=Active(s);for(int i=0;i<80;i++)Engine.AddUnit(s,0,s.Cities[0].Tile,UnitKind.Catapult);s.Player.Gold=0;for(int i=0;i<3;i++){Step(s);Assert(t.LastFee==0&&t.LastScience==0,"Unfunded science awarded");}Assert(t.Status==TreatyStatus.Broken&&t.BreachedBy==0&&t.PayoutTo==100&&t.EscrowFrom+t.EscrowTo==0&&s.Player.Gold>=0,"Default failed to settle actual escrow");Valid(s);});
        test("Mutual funding failure returns each bond without inventing an aggressor",()=>{var s=Fixture();var t=Active(s);foreach(int owner in new[]{0,1}){for(int i=0;i<80;i++)Engine.AddUnit(s,owner,s.Cities.First(c=>c.Owner==owner).Tile,UnitKind.Catapult);s.Factions[owner].Gold=0;}for(int i=0;i<3;i++)Step(s);Assert(t.Status==TreatyStatus.Cancelled&&t.BreachedBy==null&&t.PayoutFrom==50&&t.PayoutTo==50&&t.LastScience==0,"Mutual failure punished an invented offender");Valid(s);});
        test("A completed research treaty refunds both deposits once at its exact boundary",()=>{var s=Fixture();var t=Active(s);int expiry=t.ExpiresTurn!.Value;while(s.Turn<expiry)Step(s);Assert(t.Status==TreatyStatus.Completed&&t.FundedPhases==12&&t.PayoutFrom==50&&t.PayoutTo==50,"Wrong final research phase or payout");double a=t.TotalScience;Step(s);Assert(t.TotalScience==a&&t.PayoutFrom==50,"Expired contract repeated its reward");Valid(s);});
        test("Peace guarantees lock funds without blocking the legitimate war preview",()=>{var s=Fixture();var t=Active(s,TreatyKind.PeaceGuarantee);Step(s);Assert(Treaties.HasGuarantee(s,0,1)&&DiplomaticCouncil.PreviewWar(s,1,WarReason.Conquest).Allowed&&Treaties.BreachWarning(s,0,1).Contains("80"),"Guarantee silently became an unbreakable truce");Valid(s);});
        test("Breaking a guarantee pays the victim both real deposits exactly once",()=>{var s=Fixture();var t=Active(s,TreatyKind.PeaceGuarantee);Step(s);double gold=s.Factions[1].Gold;s.Player.Prestige=100;int stability=s.Player.Stability;Assert(Treaties.Break(s,t.Id).Success&&t.Status==TreatyStatus.Broken&&s.Factions[1].Gold==gold+160&&t.PayoutTo==160&&s.Player.Stability==stability-6,"Breach settlement incorrect");string json=SaveGame.Serialize(s);Assert(!Treaties.Break(s,t.Id).Success&&SaveGame.Serialize(s)==json,"Double compensation");Valid(s);});
        test("The actual war action automatically forfeits the aggressor's guarantee",()=>{var s=Fixture();var t=Active(s,TreatyKind.PeaceGuarantee);Step(s);double victim=s.Factions[1].Gold;Assert(Engine.DeclareWar(s,1,WarReason.Conquest).Success&&t.Status==TreatyStatus.Broken&&t.BreachedBy==0&&s.Factions[1].Gold==victim+160,"War bypassed settlement");Valid(s);});
        test("A recorded AI declaration is settled by the ordinary turn before economic effects",()=>{var s=Fixture();var t=Active(s,TreatyKind.PeaceGuarantee);Step(s);var control=SaveGame.Deserialize(SaveGame.Serialize(s));foreach(var world in new[]{s,control}){world.Relation(0,1).War=true;world.Relation(0,1).Trade=false;world.Wars.Add(new(){Id=world.NextWarId++,A=0,B=1,Aggressor=1,Reason=WarReason.Conquest,TargetCityId=world.Cities[0].Id,GoalDeclared=true,StartedTurn=world.Turn,StartingCitiesA=world.Cities.Where(c=>c.Owner==0).Select(c=>c.Id).ToList(),StartingCitiesB=world.Cities.Where(c=>c.Owner==1).Select(c=>c.Id).ToList()});}control.Treaties=[];control.NextTreatyId=1;Step(s);Step(control);Assert(t.Status==TreatyStatus.Broken&&t.BreachedBy==1&&Math.Abs(s.Player.Gold-control.Player.Gold-160)<.00001,"AI escaped bond forfeiture");Valid(s);});
        test("The actual embargo action breaks research but retains a peace guarantee",()=>{var s=Fixture();var t=Active(s);Step(s);double victim=s.Factions[1].Gold;Assert(Engine.SetTradePolicy(s,TradePolicy.Embargo).Success&&t.Status==TreatyStatus.Broken&&s.Factions[1].Gold==victim+100,"Embargo skipped research obligations");Valid(s);var peace=Fixture();var g=Active(peace,TreatyKind.PeaceGuarantee);Step(peace);Assert(Engine.SetTradePolicy(peace,TradePolicy.Embargo).Success&&g.Status==TreatyStatus.Active,"Embargo unexpectedly ended a peace-only guarantee");Valid(peace);});
        test("War cancels travelling proposals without inventing a signed bond",()=>{var s=Fixture();Treaties.Propose(s,1,TreatyKind.Research,12);Step(s);Assert(Engine.DeclareWar(s,1,WarReason.Conquest).Success&&s.Treaties.Single().Status==TreatyStatus.Cancelled&&s.Treaties.Single().PayoutFrom==0,"Unsigned compensation created");Valid(s);});
        test("Elimination returns signed security without fabricating an offender",()=>{var s=Fixture();var t=Active(s,TreatyKind.PeaceGuarantee);foreach(var c in s.Cities.Where(c=>c.Owner==1).ToArray())ProvincialPolitics.Transfer(s,c,2);Step(s);Assert(t.Status==TreatyStatus.Cancelled&&t.BreachedBy==null&&t.PayoutFrom==80&&t.PayoutTo==80,"Elimination invented a breach");Valid(s);});
        test("Incoming AI proposals cannot automatically spend player funds or sign",()=>{var s=Fixture();double a=s.Player.Gold,b=s.Factions[1].Gold;Assert(Treaties.Propose(s,0,TreatyKind.PeaceGuarantee,24,1).Success&&s.Player.Gold==a&&s.Factions[1].Gold==b-10,"Incoming message charged player");var t=s.Treaties.Single();Step(s);Step(s);Assert(t.Status==TreatyStatus.AwaitingPlayer&&t.EscrowFrom==0&&t.SignedTurn==null,"Incoming auto-signature");Assert(Treaties.Ratify(s,t.Id).Success&&t.EscrowFrom==80&&t.EscrowTo==80,"Incoming explicit ratification failed");Valid(s);});
        test("Optional AI negotiations begin after a real first contact",()=>{var s=Fixture();var t=Ready(s);Treaties.Reject(s,t.Id);s.Turn=21;s.PendingEvent=null;s.PendingCityId=null;double a=s.Player.Gold;Treaties.ManageAi(s,1);Assert(s.Treaties.Count==2&&s.Treaties.Last().From==1&&s.Player.Gold==a,"AI channel or explicit consent incorrect");Valid(s);});
        test("Two pending commitments enforce the global party limit",()=>{var s=Fixture();s.Factions[2].Technologies.Add("writing");s.Factions[3].Technologies.Add("writing");Treaties.Propose(s,1,TreatyKind.Research,12);Assert(Treaties.Propose(s,2,TreatyKind.PeaceGuarantee,12).Success,"Second partner rejected");string json=SaveGame.Serialize(s);Assert(!Treaties.Propose(s,3,TreatyKind.PeaceGuarantee,12).Success&&SaveGame.Serialize(s)==json,"Commitment cap bypassed");});
        test("Saving mid-negotiation and during paid cooperation preserves deterministic continuation",()=>{foreach(bool signed in new[]{false,true}){var s=Fixture();if(signed)Active(s);else Treaties.Propose(s,1,TreatyKind.Research,12);var copy=SaveGame.Deserialize(SaveGame.Serialize(s));for(int i=0;i<4;i++){Step(s);Step(copy);Assert(SaveGame.Serialize(s)==SaveGame.Serialize(copy),"Diplomatic continuation diverged");}}});
        test("Real v25 data migrates without agreements and keeps an exact v25 backup",()=>{var s=Fixture();s.Player.EraLegacies.Add(0);var node=JsonNode.Parse(SaveGame.Serialize(s))!;node["Version"]=25;node.AsObject().Remove("Treaties");node.AsObject().Remove("NextTreatyId");string old=node.ToJsonString();var loaded=SaveGame.Deserialize(old);Assert(loaded.Treaties.Count==0&&loaded.NextTreatyId==1&&loaded.Player.EraLegacies.Contains(0)&&loaded.Version==SaveGame.CurrentVersion,"Migration lost legacy or invented agreement");string dir=Path.Combine(Path.GetTempPath(),"crown-treaty-"+Guid.NewGuid());Directory.CreateDirectory(dir);string path=Path.Combine(dir,"old.crown");try{File.WriteAllText(path,old);SaveGame.Write(loaded,path);Assert(File.ReadAllText(path+".v25.bak")==old,"Exact v25 backup absent");}finally{foreach(string file in new[]{path,path+".tmp",path+".v25.bak"})File.Delete(file);Directory.Delete(dir);}});
        test("The war forecast explicitly warns about the same confiscated bond",()=>{var s=Fixture();Active(s,TreatyKind.PeaceGuarantee);Step(s);var preview=DiplomaticCouncil.PreviewWar(s,1,WarReason.Conquest);Assert(preview.Allowed&&preview.Reason.Contains("80")&&preview.Reason.Contains("stabilność -6"),"War preview concealed the treaty cost");});
        test("Validation rejects duplicate pending negotiations",()=>{var s=Fixture();var t=Ready(s);s.Treaties.Add(new(){Id=s.NextTreatyId++,From=t.From,To=t.To,Kind=t.Kind,Duration=t.Duration,SentTurn=t.SentTurn,DueTurn=t.DueTurn,DeadlineTurn=t.DeadlineTurn,ReplyTurn=t.ReplyTurn,Status=t.Status,Report="Duplicate"});bool rejected=false;try{Valid(s);}catch(InvalidDataException){rejected=true;}Assert(rejected,"Duplicate negotiation accepted");});
        test("Validation rejects forged deposits payouts scientific evidence and older schemas",()=>{for(int mode=0;mode<12;mode++){var s=Fixture();var t=Active(s);Step(s);switch(mode){case 0:t.EscrowFrom++;break;case 1:t.PayoutTo=50;break;case 2:t.LastScience++;break;case 3:t.LastIncomeFrom=-1;break;case 4:t.LastPhaseTurn=s.Turn;break;case 5:t.Duration=13;break;case 6:t.ExpiresTurn++;break;case 7:t.TotalScience=99999;break;case 8:s.NextTreatyId=t.Id;break;case 9:s.Version=25;break;case 10:t.From=3;break;case 11:t.SignedTurn=null;break;}bool rejected=false;try{Valid(s);}catch(InvalidDataException){rejected=true;}Assert(rejected,"Forged treaty accepted");}});
    }
}
